"""Build a report draft JSON and its approval preview from a folder of manuscript files.

One builder for every revision of a report: the text lives in manuscript files, numbers come from
the project's facts module ({{name}} placeholders), and each build validates the draft with the
engine and runs the text and source checks. With --render it also renders a candidate HWPX outside
the repository (page SVG/PNG and a PDF) and runs the layout checks.

    python3 <skill>/tools/build_report.py --config docs/report/report.json            # draft + preview
    python3 <skill>/tools/build_report.py --config docs/report/report.json --render <dir>

The project settings file (JSON, paths relative to the project root = --root, default: the git top
level of the settings file) names the manuscript folder, the draft and preview files, the report
form (template) and optional checks; see tools/README.md.

Manuscript format (files named NN-name.md, read in file-name order; form.json in the same folder
holds the form parts: title, goals, summary):
    # 제목 / ## 제목 / ### 제목          heading1 / heading2 / heading3 (numbers are added by the engine)
    ◯ 문장                               statement; continuation lines are indented by two or more spaces
    - 문장                               detail
    > src: path; path                    source of the block above (heading sources apply to the blocks below
                                         them that have none)
    ![캡션](path, path){cols=2}           figure_grid with an angle caption; cols defaults to the image count
    [표] 캡션 {ratios=20,60,20}{env}      table; the markdown table follows on the next lines. {env} marks the
                                         tools/environment table, the only place tool and model names may appear
    %% ...                               author note, not printed
"""
import argparse
import datetime as dt
import importlib.util
import json
import os
import re
import struct
import subprocess
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ENGINE = TOOLS.parent / 'engine'

# ---------------------------------------------------------------- settings


class Settings:
    """The project's report settings (report.json) with paths resolved against the project root."""

    def __init__(self, path, root=None):
        self.path = Path(path).resolve()
        data = json.loads(self.path.read_text())
        self.root = Path(root).resolve() if root else git_root(self.path.parent)
        self.data = data
        self.project = data['project']
        self.template = data.get('template')
        self.content = self.root / data['content']
        self.draft = self.root / data['draft']
        self.preview = self.root / data['preview']
        self.target = self.root / data['target'] if data.get('target') else None
        # the engine's journal for this report: report.json "journal", else report-journal.jsonl next to the target
        self.journal = (self.root / data['journal'] if data.get('journal')
                        else self.target.parent / 'report-journal.jsonl' if self.target else None)
        self.facts = self.root / data['facts'] if data.get('facts') else None
        self.title = data.get('title', '보고서')
        checks = data.get('checks', {})
        self.worklog = WORKLOG + checks.get('worklog', [])
        self.internal = INTERNAL_RES + [(p, '내부 기호·영문 약어') for p in checks.get('internalTerms', [])]
        self.models = MODEL_NAMES + checks.get('modelNames', [])
        self.legacy = checks.get('legacySources', [])
        self.allow = set(checks.get('allowTerms', []))
        # the achievement list the manuscript is checked against, and the page-by-page render record
        self.achievements = self.root / data['achievements'] if data.get('achievements') else None
        self.page_check = self.root / data['pageCheck'] if data.get('pageCheck') else None
        # globs of result, evaluation and test records the achievement list has to account for, added to the
        # records the tool finds itself (evidence_records); and the structure template of the report
        self.evidence = data.get('evidence', [])
        self.structure = data.get('structure')

    def rel(self, path):
        return os.path.relpath(path, self.root)


def git_root(start):
    try:
        out = subprocess.run(['git', 'rev-parse', '--show-toplevel'], cwd=start, capture_output=True, text=True, check=True)
        return Path(out.stdout.strip())
    except (subprocess.CalledProcessError, FileNotFoundError):
        return Path(start).resolve()


def load_facts(settings):
    if not settings.facts:
        return {}
    spec = importlib.util.spec_from_file_location('report_facts', settings.facts)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.facts()


def load_form(path):
    """Form data from the content folder, if any. Old tooling wrote {"goals": ..., "summary": ...}."""
    return json.loads(path.read_text()) if path.exists() else {}


def form_spec(template):
    """The engine's form.json of a template (for the preview's form-table labels)."""
    if not template:
        return {}
    path = ENGINE / 'forms' / template / 'form.json'
    return json.loads(path.read_text()) if path.exists() else {}

# ---------------------------------------------------------------- content parsing


HEADINGS = {'#': 'heading1', '##': 'heading2', '###': 'heading3'}
FIGURE_RE = re.compile(r'^!\[(?P<caption>.+?)\]\((?P<images>[^)]+)\)(?P<opts>(?:\{[^}]*\})*)\s*$')
TABLE_RE = re.compile(r'^\[표\]\s*(?P<caption>.+?)\s*(?P<opts>(?:\{[^}]*\})*)\s*$')
PLACEHOLDER_RE = re.compile(r'\{\{(\w+)\}\}')


def _opts(text):
    opts = {}
    for item in re.findall(r'\{([^}]*)\}', text or ''):
        key, _, value = item.partition('=')
        opts[key.strip()] = value.strip() if value else True
    return opts


def _fill(text, facts, where):
    def sub(match):
        if match.group(1) not in facts:
            raise KeyError(f'{where}: unknown fact {{{{{match.group(1)}}}}}')
        return str(facts[match.group(1)])
    return PLACEHOLDER_RE.sub(sub, text)


def parse(path, facts):
    blocks = []
    lines = path.read_text().splitlines()
    i = 0
    while i < len(lines):
        raw = lines[i]
        where = f'{path.name}:{i + 1}'
        line = raw.strip()
        i += 1
        if not line or line.startswith('%%'):
            continue
        if raw.startswith('  ') and blocks and blocks[-1]['type'] in ('statement', 'detail'):
            blocks[-1]['text'] += ' ' + _fill(line, facts, where)
            continue
        marker, _, rest = line.partition(' ')
        if marker in HEADINGS:
            blocks.append({'type': HEADINGS[marker], 'text': _fill(rest.strip(), facts, where)})
        elif marker == '◯':
            blocks.append({'type': 'statement', 'text': _fill(rest.strip(), facts, where)})
        elif marker == '-':
            blocks.append({'type': 'detail', 'text': _fill(rest.strip(), facts, where)})
        elif line.startswith('> src:'):
            if not blocks:
                raise ValueError(f'{where}: source line before any block')
            blocks[-1]['source'] = line[len('> src:'):].strip()
        elif FIGURE_RE.match(line):
            m = FIGURE_RE.match(line)
            images = [p.strip() for p in m['images'].split(',')]
            opts = _opts(m['opts'])
            blocks.append({'type': 'figure_grid', 'images': images, 'columns': int(opts.get('cols', len(images))),
                           'caption': _fill(m['caption'], facts, where), 'captionStyle': 'angle'})
        elif TABLE_RE.match(line):
            m = TABLE_RE.match(line)
            opts = _opts(m['opts'])
            rows = []
            while i < len(lines) and lines[i].strip().startswith('|'):
                cells = [c.strip() for c in lines[i].strip().strip('|').split('|')]
                if not all(re.fullmatch(r':?-{3,}:?', c) for c in cells):
                    rows.append([_fill(c, facts, f'{path.name}:{i + 1}') for c in cells])
                i += 1
            if len(rows) < 2:
                raise ValueError(f'{where}: table needs a header row and at least one body row')
            block = {'type': 'table', 'caption': _fill(m['caption'], facts, where), 'headers': rows[0], 'rows': rows[1:]}
            if 'ratios' in opts:
                block['colWidthRatios'] = [float(x) for x in opts['ratios'].split(',')]
            if opts.get('env'):
                block['_env'] = True
            blocks.append(block)
        else:
            raise ValueError(f'{where}: unrecognised line: {line[:40]}')
    return blocks


def inherit_sources(blocks):
    current = {1: None, 2: None, 3: None}
    for block in blocks:
        if block['type'].startswith('heading'):
            level = int(block['type'][-1])
            current[level] = block.get('source')
            for deeper in range(level + 1, 4):
                current[deeper] = None
        elif 'source' not in block:
            inherited = current[3] or current[2] or current[1]
            if inherited:
                block['source'] = inherited
                block['_inherited'] = True
    return blocks

# ---------------------------------------------------------------- text checks

# Work-log and trial-and-error wording (report-writing.md §1). Candidates for a human look, not errors:
# a few can be right in context. Projects add their own words in report.json checks.worklog.
WORKLOG = ['재실행', '다시 실행', '교체하였', '세션', '권한', '회차', '브랜치', '커밋', '해시', '시행착오',
           '첫 실행', '처음 실행', '개발 담당', '작업 폴더', '반영하였', '고쳤', '수정하였', '오류가 발견',
           '재설계', '철회', '검토 지적', '에이전트가 스스로', '프롬프트']
INTERNAL_RES = [
    # ASCII boundaries: Korean particles glue to codes ("a25e327에서", "engine.js를")
    (r'(?<![0-9A-Za-z])[0-9a-f]{7,40}(?![0-9A-Za-z])', 'commit·해시 형태'),
    (r'[A-Za-z0-9_-]+\.(?:py|md|json|mjs|js|ts|png|jpg|csv|xlsx|hwpx|sh|ipynb|yaml|yml|toml)(?![A-Za-z0-9])', '파일 이름'),
    (r'(?<![\w가-힣])(?:[\w.-]+/)+[\w.-]+', '경로'),
    (r'(?<![A-Za-z0-9])[A-Za-z]+_[A-Za-z_]+(?![A-Za-z0-9])', '코드 식별자'),
    (r'(?<![A-Za-z0-9])[A-Z]{2,6}s?(?![A-Za-z0-9])', '영문 약어'),
    (r'(?<![A-Za-z])(?:complete|partial|unknown|not_checked|pass|fail|todo|wip)(?![A-Za-z])', '영문 상태값'),
]
# Names of the tools that helped do the work (AI assistants, editors) belong in the tools/environment table
# ({env}). A model or instrument that is itself studied is named in the text: list it in checks.allowTerms.
MODEL_NAMES = ['gpt', 'chatgpt', 'claude', 'opus', 'sonnet', 'haiku', 'gemini', 'llama', 'qwen', 'mistral',
               'deepseek', 'codex', 'copilot']
META = ['본 절', '본 보고서에서는', '본 연구에서는', '살펴보', '의의가 크', '중요한 의미', '다음과 같음', '아래와 같음']


UNIT_RE = re.compile(r'[A-Za-zµμ°%]{1,4}/[A-Za-z0-9²³µμ]{1,4}')


def is_unit(term):
    """A unit such as mg/L or km/h (Korean particles may follow), not a path."""
    ascii_part = re.match(r'[!-~µμ°²³]+', term)
    return bool(ascii_part and UNIT_RE.fullmatch(ascii_part.group(0)))


def block_text(block):
    parts = [block.get('text', ''), block.get('caption', '')]
    if block['type'] == 'table':
        parts += block['headers'] + [c for row in block['rows'] for c in row]
    return ' '.join(p for p in parts if p)


ACRONYM = re.compile(r'[A-Z][A-Z0-9/&-]{1,7}')
# abbreviations a general reader knows; any other allowed abbreviation is spelled out once in the text
COMMON_ACRONYMS = {'AI', 'PDF', 'CPU', 'GPU', 'UI', 'URL', 'CSV', 'API', 'GIS', 'GPS', 'HWPX', 'DB', 'PC', 'OS', 'IT'}


def text_checks(blocks, form=None, settings=None):
    """Wording candidates in every printed string: block text, captions, table cells and form parts."""
    worklog = settings.worklog if settings else WORKLOG
    internal = settings.internal if settings else INTERNAL_RES
    models = settings.models if settings else MODEL_NAMES
    allow = settings.allow if settings else set()
    model_re = re.compile(r'(?i)(?<![a-z])(?:' + '|'.join(map(re.escape, models)) + r')(?![a-z])')
    items = [(n, block_text(block), block.get('_env')) for n, block in enumerate(blocks, 1)]
    explained = squeeze(' '.join(body for _, body, _ in items))
    for key, value in (form or {}).items():
        rows = [[value]] if isinstance(value, str) else value
        items += [(f'양식 {key} {r}', ' '.join(row), False) for r, row in enumerate(rows, 1)]
    found = []
    for n, body, env in items:
        for term in worklog:
            if term in body:
                found.append((n, '작업 기록 어휘', term))
        for term in META:
            if term in body:
                found.append((n, '안내·평가 문장', term))
        if env:
            continue
        for pattern, label in internal:
            for m in re.finditer(pattern, body):
                term = m.group(0)
                if label == '경로' and is_unit(term):
                    continue
                if term not in allow:
                    found.append((n, label, term))
                elif ACRONYM.fullmatch(term) and term not in COMMON_ACRONYMS and f'({term})' not in explained:
                    # an allowed abbreviation still needs its Korean meaning once: "공간 교차검증(CV)"
                    found.append((n, '풀이 없는 약어(허용 목록에 있음)', term))
        allow_lower = {a.lower() for a in allow}
        for m in model_re.finditer(body):
            if m.group(0).lower() not in allow_lower:
                found.append((n, '작업 도구·모델 이름(환경 표 밖)', m.group(0)))
    return found


def source_checks(blocks, settings):
    issues = []
    for n, block in enumerate(blocks, 1):
        if block['type'].startswith('heading'):
            continue
        source = block.get('source')
        if not source:
            issues.append((n, '근거 없음', ''))
            continue
        for part in source.split(';'):
            path = part.strip().split(' ')[0]
            if not path:
                continue
            if any(path.startswith(p) or p in path for p in settings.legacy):
                issues.append((n, '옛 판본 근거', path))
            probe = path.split('#')[0]
            if '*' in probe:
                if not list(settings.root.glob(probe)):
                    issues.append((n, '근거 경로 없음', path))
            elif not (settings.root / probe).exists():
                issues.append((n, '근거 경로 없음', path))
    return issues


def markdown_tables(text):
    """Markdown tables of a file as lists of row dicts keyed by the header cells."""
    tables, rows = [], []
    for line in text.splitlines() + ['']:
        if line.strip().startswith('|'):
            rows.append([c.strip() for c in line.strip().strip('|').split('|')])
            continue
        if len(rows) >= 2 and set(''.join(rows[1])) <= set('-: '):
            tables.append([dict(zip(rows[0], r)) for r in rows[2:]])
        rows = []
    return tables


def squeeze(text):
    return re.sub(r'\s+', '', text)


def printed_text(blocks, form):
    parts = [block_text(b) for b in blocks]
    for value in (form or {}).values():
        parts += [value] if isinstance(value, str) else [c for row in value for c in row]
    return squeeze(' '.join(parts))


def achievement_checks(settings, blocks, form):
    """The achievement list against the manuscript: each listed result sits in its section with its key
    numbers, and each planned figure is in the draft. Returns (findings, counts)."""
    if not settings.achievements:
        return ['성과 목록 파일이 설정되지 않음(report.json "achievements"). 성과 목록을 먼저 만든다'], {}
    if not settings.achievements.exists():
        return [f'성과 목록 파일 없음: {settings.rel(settings.achievements)}'], {}
    tables = markdown_tables(settings.achievements.read_text())
    results = next((t for t in tables if t and '핵심 수치' in t[0]), None)
    figures = next((t for t in tables if t and '그림' in t[0] and '역할' in t[0]), None)
    found = []
    if results is None:
        return ['성과 목록에 성과 표(머리에 "핵심 수치")가 없음'], {}
    headings = [squeeze(b['text']) for b in blocks if b['type'].startswith('heading')]
    text = printed_text(blocks, form)
    used = {img for b in blocks if b['type'] == 'figure_grid' for img in b['images']}
    kept = [r for r in results if not r.get('제외 이유', '').strip()]
    for r in kept:
        name = f"성과 {r.get('번호', '?')} {r.get('성과', '')}"
        section = squeeze(r.get('절', ''))
        if section and not any(section in h for h in headings):
            found.append(f"{name}: 넣을 절 '{r.get('절')}'이 원고 제목에 없음")
        for value in [v.strip() for v in r.get('핵심 수치', '').split(';') if v.strip()]:
            if squeeze(value) not in text:
                found.append(f"{name}: 핵심 수치 '{value}'가 본문에 없음")
        for path in [v.strip().split(' ')[0] for v in r.get('근거', '').split(';') if v.strip()]:
            if not (settings.root / path.split('#')[0]).exists():
                found.append(f"{name}: 근거 경로 없음 {path}")
    # one achievement per section: several results under one heading become a summary paragraph
    by_section = {}
    for r in kept:
        # the interpretation scope closes its result section, so a 범위 row may share it
        if r.get('절', '').strip() and r.get('구분', '').strip() != '범위':
            by_section.setdefault(squeeze(r['절']), []).append(r.get('번호', '?'))
    for section, numbers in by_section.items():
        if len(numbers) > 1:
            found.append(f"절 '{section}'에 성과 {len(numbers)}개({', '.join(numbers)}): 성과마다 소절을 두고 "
                         '성과 목록의 절을 그 소절 제목으로 적는다')
    # every evaluation and test record is either reported or excluded with a reason. The tool finds the
    # records itself, so a short evidence list cannot hide one; a cited file or folder accounts for a record
    cited = [v.strip().split(' ')[0].split('#')[0].rstrip('/') for r in results for v in r.get('근거', '').split(';')
             if v.strip()]
    for rel in evidence_records(settings):
        if not any(rel == c or c.startswith(rel + '/') or rel.startswith(c + '/') for c in cited if c):
            found.append(f'성과 목록이 다루지 않은 근거 기록: {rel}(성과로 넣거나 제외 이유와 함께 적는다)')
    found += structure_findings(settings, kept, figures or [])
    # a section that reports measured results shows them in a figure
    for section in {squeeze(r['절']) for r in kept if r.get('절', '').strip() and r.get('핵심 수치', '').strip()
                    and '결과' in r.get('구분', '')}:
        span = section_blocks(blocks, section)
        if span is not None and not any(b['type'] == 'figure_grid' for b in span):
            found.append(f"결과 수치가 있는 절 '{section}'에 그림이 없음(결과를 보여 주는 그림을 두거나 이유를 성과 목록에 적는다)")
    for r in figures or []:
        path = r.get('그림', '').strip().strip('`')
        if path and not r.get('제외 이유', '').strip() and path not in used:
            found.append(f"그림 계획 {r.get('번호', '?')} {path}: 초안에 없음")
    if figures is None:
        found.append('성과 목록에 그림 계획 표(머리에 "그림", "역할")가 없음')
    return found, {'results': len(kept), 'excluded': len(results) - len(kept), 'figures': len(figures or [])}


RECORD_DIRS = ('evals', 'results', 'experiments')
SKIP_DIRS = {'node_modules', '.git', '.venv', '__pycache__'}


def evidence_records(settings):
    """Result, evaluation and test records, as project-relative paths: every folder directly under a folder
    named evals, results or experiments that holds a README.md or summary.json, plus report.json evidence."""
    report_dir = settings.target.parent if settings.target else None
    records = set()
    for name in RECORD_DIRS:
        for top in settings.root.rglob(name):
            if not top.is_dir() or SKIP_DIRS & set(top.relative_to(settings.root).parts):
                continue
            if report_dir and (top == report_dir or report_dir in top.parents):
                continue
            for record in top.iterdir():
                if record.is_dir() and ((record / 'README.md').exists() or (record / 'summary.json').exists()):
                    records.add(settings.rel(record))
    for pattern in settings.evidence:
        records.update(settings.rel(p) for p in settings.root.glob(pattern))
    return sorted(records)


STRUCTURES = json.loads((TOOLS / 'structures.json').read_text())


def structure_findings(settings, kept, figures):
    """The structure template: each work unit (작업) has a row, in its own section, for every required
    role, and the figures its method and results need."""
    if not settings.structure:
        return ['report.json "structure"가 없음: 보고서 유형을 고른다(' + ', '.join(k for k in STRUCTURES if k[0] != '_')
                + ', 또는 "none")']
    if settings.structure == 'none':
        return []
    spec = STRUCTURES.get(settings.structure)
    if spec is None:
        return [f'알 수 없는 구조 틀: {settings.structure}']
    found = []
    units = {}
    for r in kept:
        unit = r.get('작업', '').strip()
        roles = [role for role in spec['roles'] if role in r.get('구분', '')]
        if not unit:
            found.append(f"성과 {r.get('번호', '?')}: 작업 칸이 비어 있음")
            continue
        if len(roles) != 1:
            found.append(f"성과 {r.get('번호', '?')}: 구분은 {'/'.join(spec['roles'])} 중 하나만 적는다(지금 '{r.get('구분', '')}')")
        units.setdefault(unit, []).append((roles[0] if roles else None, r))
    for unit, rows in units.items():
        present = {role for role, _ in rows}
        missing = [role for role in spec['required'] if role not in present]
        if missing:
            found.append(f"작업 '{unit}'에 {', '.join(missing)} 성과가 없음(구조 틀 {settings.structure})")
        unit_figures = [f for f in figures if f.get('작업', '').strip() == unit and not f.get('제외 이유', '').strip()]
        roles = [f.get('역할', '') for f in unit_figures]
        if spec['figures']['method'] and not any(any(m in role for m in spec['figures']['method']) for role in roles):
            found.append(f"작업 '{unit}'에 {'·'.join(spec['figures']['method'])} 그림이 없음")
        measured = any(role == '결과' and r.get('핵심 수치', '').strip() for role, r in rows)
        if measured and not any(spec['figures']['result'] in role for role in roles):
            found.append(f"작업 '{unit}'에 결과 그림이 없음(결과 수치가 있는 작업)")
    return found


def section_blocks(blocks, section):
    """Blocks under the first heading whose text contains section, up to the next heading of the same or a
    higher level (None when no heading matches)."""
    for i, b in enumerate(blocks):
        if b['type'].startswith('heading') and section in squeeze(b['text']):
            level = b['type']
            end = next((j for j in range(i + 1, len(blocks)) if blocks[j]['type'].startswith('heading')
                        and blocks[j]['type'] <= level), len(blocks))
            return blocks[i + 1:end]
    return None


def page_check_findings(settings, pages):
    """Pages of the render that the page-by-page record (report.json "pageCheck") does not cover."""
    if not settings.page_check:
        return ['쪽별 확인 기록 파일이 설정되지 않음(report.json "pageCheck")']
    if not settings.page_check.exists():
        return [f'쪽별 확인 기록 없음: {settings.rel(settings.page_check)}(렌더한 쪽 이미지를 보고 쪽마다 적는다)']
    seen = set()
    for table in markdown_tables(settings.page_check.read_text()):
        for r in table:
            number = re.sub(r'\D', '', r.get('쪽', ''))
            if number and r.get('본 것', '').strip():
                seen.add(int(number))
    missing = [n for n in range(1, pages + 1) if n not in seen]
    return [f"쪽별 확인 기록에 없는 쪽: {', '.join(map(str, missing))}"] if missing else []


def image_info(path):
    """Pixels and the pHYs resolution of a PNG figure (the engine takes PNG only)."""
    data = Path(path).read_bytes()
    if not data.startswith(b'\x89PNG'):
        raise ValueError(f'{path}: not a PNG')
    width, height = struct.unpack('>II', data[16:24])
    dpi = None
    pos = 8
    while pos < len(data):
        length = struct.unpack('>I', data[pos:pos + 4])[0]
        kind = data[pos + 4:pos + 8]
        if kind == b'pHYs':
            ppu_x, _, unit = struct.unpack('>IIB', data[pos + 8:pos + 17])
            if unit == 1:
                dpi = ppu_x * 0.0254
            break
        if kind == b'IDAT':
            break
        pos += 12 + length
    return {'kind': 'png', 'width': width, 'height': height, 'bytes': len(data), 'dpi': dpi,
            'natural_px': width * 96 / dpi if dpi else None}


