def paragraph_map(blocks):
    """Block number (1-based) of each top-level body paragraph the engine writes, in order."""
    owners = []
    for n, block in enumerate(blocks, 1):
        if block['type'] == 'table':
            owners += [n, n] if block.get('caption') else [n]
        elif block['type'] == 'figure_grid' and block.get('captionStyle') != 'angle':
            owners += [n, n]
        else:
            owners.append(n)
    return owners


OUTLINE_LABEL = re.compile(r'^(?:[가-하]\.|\d+\)|\(\d+\))\s')


def layout_findings(blocks, checks, root):
    owners = paragraph_map(blocks)
    # the body may start with form paragraphs or an earlier report; the first block's text marks the draft.
    # Outline numbers are left out of the match: a continuation goes on from the report's numbers.
    unlabel = lambda t: OUTLINE_LABEL.sub('', t)  # noqa: E731
    first = unlabel(rendered_labels(blocks)[0] or '')[:12]
    texts = [unlabel(t.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&')) for t in checks['bodyTexts']]
    # the draft is the last thing in the body, so take the last match that leaves room for all its paragraphs
    offset = next((i for i in range(len(texts) - len(owners), -1, -1) if first and texts[i].startswith(first)), None)
    found = []
    if offset is None:
        found.append('렌더 문단과 초안 block을 맞추지 못해 쪽 끝 고립을 block 번호로 표시하지 못함')

    def owner(paragraph):
        k = paragraph - offset if offset is not None else -1
        return owners[k] if 0 <= k < len(owners) else '?'
    for v in checks['keepViolations']:
        found.append(f"{v['page']}쪽 끝에 다음 내용과 떨어진 제목·표 제목: block {owner(v['paragraph'])}")
    for paragraph in checks.get('overflow', []):
        found.append(f"쪽 아래 여백을 넘어 그려진 표·그림: block {owner(paragraph)}")
    for paragraph in checks.get('lineOverflow', []):
        found.append(f"미리보기에서 아래 여백에 걸린 글줄(rhwp 줄 배치, 한컴에서 확인): block {owner(paragraph)}")
    for paragraph in checks.get('splitTables', []):
        found.append(f"한 쪽에 들어가는 표가 두 쪽에 걸쳐 그려짐: block {owner(paragraph)}")
    if checks.get('summarySplit'):
        found.append('본문 끝의 양식 표가 두 쪽에 걸쳐 그려짐')
    for paragraph in checks.get('unresolved', []):
        found.append(f"렌더 결과에서 쪽을 판독하지 못한 문단: block {owner(paragraph)}")
    stats = checks['pageStats']
    for s, nxt in zip(stats, stats[1:]):
        if s['fill'] < 0.75 and nxt['first'] and nxt['first']['kind'] in ('table', 'image'):
            found.append(f"{s['page']}쪽이 {s['fill']:.0%}만 차고 다음 쪽이 표·그림으로 시작함")
    for s in stats:
        if s['fill'] > 1.005:
            found.append(f"{s['page']}쪽 내용이 아래 여백을 넘음(잘려 보일 수 있음)")
        if s['textRuns'] == 0 and s['controls'] == 0:
            found.append(f"{s['page']}쪽에 본문 없음(양식 표만 있거나 빈 쪽)")
    rendered_images = checks['images']
    ordered = [img for b in blocks if b['type'] == 'figure_grid' for img in b['images']]
    # a continued report also draws the earlier report's pictures: compare the last ones
    if len(rendered_images) >= len(ordered):
        for img, placed in zip(ordered, rendered_images[len(rendered_images) - len(ordered):]):
            info = image_info(root / img)
            # placed width in inches at print size (the layout reports 96 px per inch)
            printed_in = placed['widthPx'] / 96
            if info['natural_px']:
                scale = placed['widthPx'] / info['natural_px']
                if scale < 0.95:
                    found.append(f"{img}: 그린 크기의 {scale:.0%}로 축소되어 그림 글자가 작아짐. 8 pt로 그린 글자는 "
                                 f"약 {8 * scale:.1f} pt가 됨. 인쇄 폭으로 다시 그린다({placed['page']}쪽)")
            else:
                found.append(f'{img}: 그린 크기 정보가 없어 그림 글자 크기를 추정하지 못함({placed["page"]}쪽)')
            if info['width'] / printed_in < PRINT_DPI_MIN:
                found.append(f"{img}: 인쇄 해상도 약 {info['width'] / printed_in:.0f} dpi"
                             f"(권장 {PRINT_DPI_MIN} dpi 이상, {placed['page']}쪽)")
    else:
        found.append(f'렌더 이미지 {len(rendered_images)}개가 초안 이미지 {len(ordered)}개보다 적어 그림 크기 점검을 건너뜀')
    return found

