def rendered_labels(blocks, start=None):
    """Block text with the outline numbers the engine adds; start: numbers already used (continuation)."""
    counters = list(start or [0, 0, 0])
    ordinals = '가나다라마바사아자차카타파하'
    out = []
    for block in blocks:
        t = block['type']
        if t.startswith('heading'):
            level = int(t[-1]) - 1
            k = counters[level]
            counters[level] += 1
            for deeper in range(level + 1, 3):
                counters[deeper] = 0
            label = f'{ordinals[k]}.' if level == 0 else (f'{k + 1})' if level == 1 else f'({k + 1})')
            out.append(f"{label} {block['text']}")
        elif t == 'statement':
            out.append(f"◯ {block['text']}")
        elif t == 'detail':
            out.append(f"- {block['text']}")
        else:
            out.append(None)
    return out


