def continuation_paths(settings):
    """Draft and preview names of a continuation, next to the full draft (which stays untouched)."""
    return (settings.draft.with_name(f'{settings.draft.stem}.continue.json'),
            settings.preview.with_name(f'{settings.preview.stem}.continue.md'))


def build(settings, date=None, render_dir=None, out_dir=None, content=None, base=None, continuation=False):
    """continuation: a draft of new chapters only (content), to append to the current report. It fills no
    form parts, is written to <draft>.continue.json unless out_dir is given, and renders on the target."""
    if continuation:
        if content is None or Path(content).resolve() == settings.content.resolve():
            raise SystemExit('a continuation needs --content with the new chapters only (not the whole manuscript)')
        base = base or settings.target
        if base is None or not Path(base).exists():
            raise SystemExit(f'a continuation appends to an existing report; {base} does not exist')
        start = report_counters(base)
    else:
        start = None
    content = content or settings.content
    json_default, md_default = continuation_paths(settings) if continuation else (settings.draft, settings.preview)
    out_json = out_dir / json_default.name if out_dir else json_default
    out_md = out_dir / md_default.name if out_dir else md_default
    out_json.parent.mkdir(parents=True, exist_ok=True)

    facts = load_facts(settings)
    files = sorted(content.glob('[0-9][0-9]-*.md'))
    if not files:
        raise SystemExit(f'no manuscript files (NN-name.md) in {content}')
    blocks = inherit_sources([b for f in files for b in parse(f, facts)])
    form_file = content / 'form.json'
    raw_form = {} if continuation else load_form(form_file)
    form = {}
    for key, value in raw_form.items():
        if isinstance(value, str):
            form[key] = _fill(value, facts, f'{form_file.name}:{key}')
        else:
            form[key] = [[_fill(c, facts, f'{form_file.name}:{key}') for c in row] for row in value]

    session = {'date': date or dt.date.today().isoformat(), 'project': settings.project}
    clean = [{k: v for k, v in b.items() if not k.startswith('_')} for b in blocks]
    draft = {'session': session, **({'template': settings.template} if settings.template else {}),
             'blocks': clean, **({'form': form} if form else {})}
    errors = validate(draft, settings.root)
    if errors:
        raise SystemExit('draft validation failed (nothing written):\n' + '\n'.join(errors))
    out_json.write_text(json.dumps(draft, ensure_ascii=False, indent=1) + '\n')

    text_found = text_checks(blocks, form, settings)
    source_found = source_checks(blocks, settings)
    coverage, counts = achievement_checks(settings, blocks, form)
    coverage += form_cell_findings(form) + facts_findings(settings, facts, blocks)
    layout = None
    if render_dir:
        checks = render(out_json, render_dir, settings.root, base)
        findings = layout_findings(blocks, checks, settings.root) + page_check_findings(settings, checks['pages'])
        layout = {'pages': checks['pages'], 'findings': findings}
        (render_dir / 'layout-checks.json').write_text(json.dumps(checks, ensure_ascii=False, indent=1))
    out_md.write_text(stamped(preview(settings, draft, blocks, text_found, source_found, form, layout, out_md,
                                      out_json, content, continuation, start, coverage, counts)))
    return {'blocks': len(blocks), 'text': len(text_found), 'sources': len(source_found), 'layout': layout,
            'coverage': len(coverage), 'draft': out_json, 'preview': out_md}


STAMP = re.compile(r'\n<!-- build_report sha256:([0-9a-f]{64}) -->\n$')


def stamped(text):
    """The preview with a closing hash of its own text: the checks it reports are the tool's, not edited."""
    import hashlib
    return f"{text}\n<!-- build_report sha256:{hashlib.sha256(text.encode()).hexdigest()} -->\n"


def preview_intact(path):
    """True when the preview is as the tool wrote it, False when edited, None when there is none."""
    import hashlib
    path = Path(path)
    if not path.exists():
        return None
    text = path.read_text()
    m = STAMP.search(text)
    return bool(m) and hashlib.sha256(text[:m.start()].encode()).hexdigest() == m.group(1)


FORM_CELL_MAX = 40


NUMBER = re.compile(r'\d[\d,.]*\s*(?:%|개|건|셀|분|배|종|명|회|km|mg/L|pt|쪽)')


def facts_findings(settings, facts, blocks):
    """Measured numbers written by hand when the facts module gives nothing (or is missing)."""
    if facts:
        return []
    count = sum(len(NUMBER.findall(block_text(b))) for b in blocks if not b.get('_env'))
    if count >= 5:
        return [f'원고에 수치 {count}개가 있으나 facts 모듈이 값을 주지 않음. 결과 파일에서 계산해 {{{{이름}}}}으로 넣는다']
    return []


def form_cell_findings(form):
    """Form table cells long enough to wrap into many lines in a narrow column (keep them short)."""
    found = []
    for r, row in enumerate((form or {}).get('summary', []), 1):
        for c, text in enumerate(row, 1):
            if len(text) > FORM_CELL_MAX:
                found.append(f'양식 요약표 {r}행 {c}열이 {len(text)}자임({FORM_CELL_MAX}자 이하로 줄이고 설명은 본문으로)')
    return found


